package com.elogistic.backend.identity.internal.web;

import com.elogistic.backend.identity.api.*;
import com.elogistic.backend.identity.internal.application.port.CurrentSessionAdmission;
import com.nimbusds.jose.*;
import com.nimbusds.jose.crypto.*;
import com.nimbusds.jwt.*;
import java.security.*;
import java.security.interfaces.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

class ProductionIdentitySecurityTests {
    private static final Instant NOW=Instant.parse("2026-10-24T00:05:00Z");
    private static final Clock CLOCK=Clock.fixed(NOW,ZoneOffset.UTC);
    private static final UUID ACCOUNT=UUID.fromString("20000000-0000-4000-8000-000000000001"),SESSION=UUID.fromString("20000000-0000-4000-8000-000000000002");
    private static KeyPair first,second;
    private ProductionAccessTokens tokens;
    @BeforeAll static void keys()throws Exception {var g=KeyPairGenerator.getInstance("RSA");g.initialize(3072);first=g.generateKeyPair();second=g.generateKeyPair();}
    @BeforeEach void fixture(){tokens=service("a",first,Map.of("a",publicKey(first)),CLOCK);}
    private static RSAPublicKey publicKey(KeyPair p){return (RSAPublicKey)p.getPublic();}
    private static ProductionAccessTokens service(String kid,KeyPair signer,Map<String,RSAPublicKey> keys,Clock clock){return new ProductionAccessTokens("https://identity.example.invalid","elogistics-browser",kid,(RSAPrivateKey)signer.getPrivate(),keys,clock);}
    private IdentitySessionCommands.AccessGrant grant(){return new IdentitySessionCommands.AccessGrant(SESSION,ACCOUNT,1,NOW,NOW.plusSeconds(900));}
    private JWTClaimsSet.Builder claims(){return new JWTClaimsSet.Builder().issuer("https://identity.example.invalid").audience("elogistics-browser").subject(ACCOUNT.toString()).jwtID(UUID.randomUUID().toString()).claim("sid",SESSION.toString()).claim("authVersion",1L).issueTime(Date.from(NOW)).notBeforeTime(Date.from(NOW)).expirationTime(Date.from(NOW.plusSeconds(900)));}
    private String signed(JWTClaimsSet c)throws Exception {return signed(c,new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).keyID("a").build(),first);}
    private String signed(JWTClaimsSet c,JWSHeader h,KeyPair key)throws Exception {var j=new SignedJWT(h,c);j.sign(new RSASSASigner((RSAPrivateKey)key.getPrivate()));return j.serialize();}
    private String compact(String header,String payload)throws Exception {var encoder=Base64.getUrlEncoder().withoutPadding();String signed=encoder.encodeToString(header.getBytes(java.nio.charset.StandardCharsets.UTF_8))+"."+encoder.encodeToString(payload.getBytes(java.nio.charset.StandardCharsets.UTF_8));var signature=Signature.getInstance("SHA256withRSA");signature.initSign(first.getPrivate());signature.update(signed.getBytes(java.nio.charset.StandardCharsets.US_ASCII));return signed+"."+encoder.encodeToString(signature.sign());}
    private void denied(String token){var e=assertThrows(IdentityCommandFailure.class,()->tokens.verify(token));assertEquals("SESSION_INVALID",e.getMessage());assertEquals(IdentityCommandFailure.Code.SESSION_INVALID,e.code());}
    private static IdentityGrantCommands.Account account(){return new IdentityGrantCommands.Account(ACCOUNT,"synthetic.identity","Synthetic Identity","identity@example.invalid","ACTIVE",List.of(),1,true);}
    private MockMvc mvc(ProductionAccessAdmission admission,IdentityCurrentSessionCommands sessions,IdentityAdministrationCommands administration){return MockMvcBuilders.standaloneSetup(new ProductionIdentityReads(sessions,administration,admission,mock(IdentityGrantCommands.class))).setControllerAdvice(new ProductionIdentityErrors()).addFilters(new ProductionReadGuard(tokens,admission,sessions,"https://portal.example.invalid")).build();}
    private MockHttpServletResponse read(MockMvc mvc,String path)throws Exception {return mvc.perform(get(path).secure(true).header("Authorization","Bearer "+tokens.issue(grant()))).andReturn().getResponse();}
    @Test void validRs256CarriesExactProductionClaims(){var c=tokens.verify(tokens.issue(grant()));assertEquals(ACCOUNT,c.accountId());assertEquals(SESSION,c.sessionId());assertEquals(1,c.authVersion());assertEquals(NOW.plusSeconds(900),c.expiresAt());}
    @Test void issuerIsSeparateFromDemo()throws Exception {denied(signed(claims().issuer("elogistics-demo").build()));}
    @Test void audienceIsExactAndSingle()throws Exception {denied(signed(claims().audience("other").build()));denied(signed(claims().audience(List.of("elogistics-browser","other")).build()));}
    @Test void noneAlgorithmRejected()throws Exception {denied(new PlainJWT(claims().build()).serialize());}
    @Test void symmetricAlgorithmConfusionRejected()throws Exception {var j=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.HS256).type(JOSEObjectType.JWT).keyID("a").build(),claims().build());j.sign(new MACSigner(new byte[32]));denied(j.serialize());}
    @Test void differentRsaAlgorithmRejected()throws Exception {denied(signed(claims().build(),new JWSHeader.Builder(JWSAlgorithm.RS512).type(JOSEObjectType.JWT).keyID("a").build(),first));}
    @Test void unknownKidRejected()throws Exception {denied(signed(claims().build(),new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).keyID("unknown").build(),first));}
    @Test void missingKidRejected()throws Exception {denied(signed(claims().build(),new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).build(),first));}
    @Test void wrongSignatureRejected()throws Exception {denied(signed(claims().build(),new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).keyID("a").build(),second));}
    @Test void unexpectedHeaderRejected()throws Exception {denied(compact("{\"alg\":\"RS256\",\"typ\":\"JWT\",\"kid\":\"a\",\"jku\":null}",claims().build().toString()));denied(signed(claims().build(),new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).keyID("a").jwkURL(java.net.URI.create("https://attacker.invalid/jwks")).build(),first));}
    @Test void nonJwtTypeRejected()throws Exception {denied(signed(claims().build(),new JWSHeader.Builder(JWSAlgorithm.RS256).type(new JOSEObjectType("other")).keyID("a").build(),first));}
    @Test void exactExpiryIsExclusive()throws Exception {denied(signed(claims().expirationTime(Date.from(NOW)).build()));}
    @Test void futureIssuanceAndNotBeforeRejected()throws Exception {denied(signed(claims().issueTime(Date.from(NOW.plusSeconds(1))).build()));denied(signed(claims().notBeforeTime(Date.from(NOW.plusSeconds(1))).build()));}
    @Test void lifetimeAboveFifteenMinutesRejected()throws Exception {denied(signed(claims().expirationTime(Date.from(NOW.plusSeconds(901))).build()));}
    @Test void allRequiredClaimsEnforced()throws Exception {for(String k:List.of("iss","aud","sub","jti","sid","iat","nbf","exp","authVersion")){var m=new HashMap<>(claims().build().toJSONObject());m.remove(k);denied(signed(JWTClaimsSet.parse(m)));}}
    @Test void staleRoleClaimsCannotBecomeAuthority()throws Exception {denied(signed(claims().claim("roles",List.of("ADMIN")).build()));}
    @Test void invalidSubjectSessionAndVersionRejected()throws Exception {denied(signed(claims().subject("not-uuid").build()));denied(signed(claims().claim("sid","bad").build()));denied(signed(claims().claim("authVersion",0).build()));denied(signed(claims().claim("authVersion",1.5).build()));}
    @Test void duplicateClaimsAndMalformedEncodingRejected()throws Exception {String payload=claims().build().toString().replaceFirst("\\{","{\"authVersion\":2,");var j=new JWSObject(new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).keyID("a").build(),new Payload(payload));j.sign(new RSASSASigner((RSAPrivateKey)first.getPrivate()));denied(j.serialize());denied(tokens.issue(grant())+"=");denied("x".repeat(9000));}
    @Test void retiredVerificationKeyWorksWithNewSigningKey()throws Exception {String old=tokens.issue(grant());var rotated=service("b",second,Map.of("a",publicKey(first),"b",publicKey(second)),CLOCK);assertEquals(ACCOUNT,rotated.verify(old).accountId());assertEquals("b",SignedJWT.parse(rotated.issue(grant())).getHeader().getKeyID());}
    @Test void emergencyKeyRemovalDeniesCompromisedKey(){String old=tokens.issue(grant());var fresh=service("b",second,Map.of("b",publicKey(second)),CLOCK);assertThrows(IdentityCommandFailure.class,()->fresh.verify(old));}
    @Test void mismatchedPrivateKeyFailsBeforeUse(){assertThrows(IllegalArgumentException.class,()->service("a",second,Map.of("a",publicKey(first)),CLOCK));}
    @Test void missingAndWeakKeysHaveSafeConfigurationFailure()throws Exception {assertThrows(IllegalArgumentException.class,()->service("a",first,Map.of(),CLOCK));var g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);var weak=g.generateKeyPair();assertEquals("IDENTITY_JWT_CONFIGURATION_INVALID",assertThrows(IllegalArgumentException.class,()->service("a",weak,Map.of("a",publicKey(weak)),CLOCK)).getMessage());}
    @Test void signingNeverExtendsApplicationDeadlines(){var c=tokens.verify(tokens.issue(new IdentitySessionCommands.AccessGrant(SESSION,ACCOUNT,1,NOW,NOW.plusSeconds(7))));assertEquals(NOW.plusSeconds(7),c.expiresAt());assertThrows(IdentityCommandFailure.class,()->tokens.issue(new IdentitySessionCommands.AccessGrant(SESSION,ACCOUNT,1,NOW,NOW.plusSeconds(901))));}
    @Test void admissionWithoutVerifiedRequestFailsClosed(){var a=new ProductionAccessAdmission((s,u,v)->NOW);assertThrows(IdentityCommandFailure.class,()->a.admit(CurrentSessionAdmission.Operation.CURRENT_SESSION,UUID.randomUUID()));}
    @Test void numericDateUsesOnlyIdenticalPersistedIssuingSecond()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW.plusNanos(123000));UUID request=UUID.randomUUID();try(var scope=a.enter(request,tokens.verify(tokens.issue(grant())))){assertEquals(NOW.plusNanos(123000),a.admit(CurrentSessionAdmission.Operation.CURRENT_SESSION,request).issuedAt());}assertThrows(IdentityCommandFailure.class,()->new ProductionAccessAdmission((s,u,v)->NOW.plusSeconds(1)).enter(request,tokens.verify(tokens.issue(grant()))));}
    @Test void requestIdAndActivityFlagAreNeverAuthority()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);UUID request=UUID.randomUUID();try(var scope=a.enter(request,tokens.verify(tokens.issue(grant())))){assertThrows(IdentityCommandFailure.class,()->a.admit(CurrentSessionAdmission.Operation.CURRENT_SESSION,UUID.randomUUID()));assertThrows(IdentityCommandFailure.class,()->a.admit(CurrentSessionAdmission.Operation.MEANINGFUL_ACTIVITY,request));}}
    @Test void admissionIsClearedOnFailureAndNeverInheritedByThread()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);UUID request=UUID.randomUUID();try(var scope=a.enter(request,tokens.verify(tokens.issue(grant())))){var pool=Executors.newSingleThreadExecutor();try{assertTrue(pool.submit(()->{try{a.admit(CurrentSessionAdmission.Operation.CURRENT_SESSION,request);return false;}catch(IdentityCommandFailure expected){return true;}}).get());}finally{pool.shutdownNow();}}assertThrows(IdentityCommandFailure.class,()->a.admit(CurrentSessionAdmission.Operation.CURRENT_SESSION,request));}
    @Test void bearerReadReturnsNoStoreAndEtagWithoutTokenEcho()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var r=read(mvc(a,current,mock(IdentityAdministrationCommands.class)),"/api/v1/auth/me");assertEquals(200,r.getStatus());assertEquals("no-store",r.getHeader("Cache-Control"));assertEquals("\"v1\"",r.getHeader("ETag"));assertNotNull(UUID.fromString(r.getHeader("X-Request-Id")));assertFalse(r.getContentAsString().contains("accessToken"));verify(current,never()).recordMeaningfulActivity(any());assertEquals(200,mvc(a,current,mock(IdentityAdministrationCommands.class)).perform(get("/api/v1/auth/me").secure(true).header("Authorization","bearer "+tokens.issue(grant()))).andReturn().getResponse().getStatus());}
    @Test void unknownRevokedOrStaleAuthoritativeSessionDenied()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenThrow(new IdentityCommandFailure(IdentityCommandFailure.Code.SESSION_INVALID));var r=read(mvc(a,current,mock(IdentityAdministrationCommands.class)),"/api/v1/auth/me");assertEquals(401,r.getStatus());assertFalse(r.getContentAsString().contains(ACCOUNT.toString()));}
    @Test void unsignedAccountAndCookieCannotAuthenticate()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);var mvc=mvc(a,current,mock(IdentityAdministrationCommands.class));var r=mvc.perform(get("/api/v1/auth/me").secure(true).cookie(new jakarta.servlet.http.Cookie("__Host-elogistics.refresh","synthetic")).header("X-Account-Id",ACCOUNT)).andReturn().getResponse();assertEquals(401,r.getStatus());verifyNoInteractions(current);}
    @Test void forwardedHeadersNeverTurnHttpIntoTrustedTls()throws Exception {var current=mock(IdentityCurrentSessionCommands.class);var mvc=mvc(new ProductionAccessAdmission((s,u,v)->NOW),current,mock(IdentityAdministrationCommands.class));assertEquals(401,mvc.perform(get("/api/v1/auth/me").header("X-Forwarded-Proto","https").header("Forwarded","proto=https").header("Authorization","Bearer "+tokens.issue(grant()))).andReturn().getResponse().getStatus());verifyNoInteractions(current);}
    @Test void nullCrossOriginAndDuplicateOriginDenied()throws Exception {var current=mock(IdentityCurrentSessionCommands.class);var mvc=mvc(new ProductionAccessAdmission((s,u,v)->NOW),current,mock(IdentityAdministrationCommands.class));for(String origin:List.of("null","https://attacker.invalid","https://portal.example.invalid/"))assertEquals(401,mvc.perform(get("/api/v1/auth/me").secure(true).header("Origin",origin)).andReturn().getResponse().getStatus());assertEquals(401,mvc.perform(get("/api/v1/auth/me").secure(true).header("Origin","https://portal.example.invalid","https://portal.example.invalid")).andReturn().getResponse().getStatus());verifyNoInteractions(current);}
    @Test void duplicateBearerAndQueryTokensDenied()throws Exception {var current=mock(IdentityCurrentSessionCommands.class);var mvc=mvc(new ProductionAccessAdmission((s,u,v)->NOW),current,mock(IdentityAdministrationCommands.class));String bearer="Bearer "+tokens.issue(grant());assertEquals(401,mvc.perform(get("/api/v1/auth/me").secure(true).header("Authorization",bearer,bearer)).andReturn().getResponse().getStatus());assertEquals(401,mvc.perform(get("/api/v1/auth/me").secure(true).header("Authorization",bearer).param("access_token","synthetic")).andReturn().getResponse().getStatus());verifyNoInteractions(current);}
    @Test void mutatingRoutesCannotBypassDeferredCsrfAndLimiter()throws Exception {var current=mock(IdentityCurrentSessionCommands.class);var mvc=mvc(new ProductionAccessAdmission((s,u,v)->NOW),current,mock(IdentityAdministrationCommands.class));for(String path:List.of("/api/v1/auth/login","/api/v1/auth/refresh","/api/v1/auth/invitations/accept","/api/v1/admin/users"))assertEquals(401,mvc.perform(post(path).secure(true).header("Authorization","Bearer "+tokens.issue(grant()))).andReturn().getResponse().getStatus());verifyNoInteractions(current);}
    @Test void objectAuthorityDenialMasksExistenceAndEtag()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);when(admin.getIdentityAccount(any(),any())).thenThrow(new IdentityCommandFailure(IdentityCommandFailure.Code.ACCOUNT_NOT_ACCESSIBLE));var r=read(mvc(a,current,admin),"/api/v1/admin/users/"+UUID.randomUUID());assertEquals(404,r.getStatus());assertNull(r.getHeader("ETag"));assertFalse(r.getContentAsString().contains("identity@example.invalid"));}
    @Test void malformedIdentifiersHaveOnlySafeValidationErrors()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);var mvc=mvc(a,current,admin);assertEquals(400,read(mvc,"/api/v1/admin/users/not-a-uuid").getStatus());assertEquals(400,read(mvc,"/api/v1/admin/users?limit=not-a-number").getStatus());verifyNoInteractions(admin);}
    @Test void configurationRejectsDemoProfileAndMissingKeyMaterial(){var env=new org.springframework.mock.env.MockEnvironment();env.setActiveProfiles("identity","demo","postgres");assertThrows(IllegalStateException.class,()->new com.elogistic.backend.identity.internal.ProductionIdentityHttpConfiguration(env));env.setActiveProfiles("identity","postgres");var config=new com.elogistic.backend.identity.internal.ProductionIdentityHttpConfiguration(env);assertEquals("IDENTITY_JWT_CONFIGURATION_INVALID",assertThrows(IllegalStateException.class,()->config.productionAccessTokens(env,CLOCK)).getMessage());}

    private MockMvc mutationMvc(ProductionAccessAdmission admission,IdentityCurrentSessionCommands current,IdentityAdministrationCommands admin,IdentityGrantCommands grants){return MockMvcBuilders.standaloneSetup(new ProductionIdentityReads(current,admin,admission,grants)).setControllerAdvice(new ProductionIdentityErrors()).addFilters(new ProductionReadGuard(tokens,admission,current,"https://portal.example.invalid")).build();}
    private org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder mutation(String suffix,String body){return post("/api/v1/admin/users/20000000-0000-4000-8000-000000000003/"+suffix).secure(true).header("Authorization","Bearer "+tokens.issue(grant())).contentType("application/json").content(body);}
    @Test void mutationAuthorityPrecedesPreconditionDisclosure()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);when(admin.getIdentityAccount(any(),any())).thenThrow(new IdentityCommandFailure(IdentityCommandFailure.Code.ACCOUNT_NOT_ACCESSIBLE));var r=mutationMvc(a,current,admin,mock(IdentityGrantCommands.class)).perform(mutation("disable","{\"reason\":\"Synthetic reason\"}")).andReturn().getResponse();assertEquals(404,r.getStatus());verify(admin,never()).disableIdentityAccount(any());verify(current,never()).recordMeaningfulActivity(any());}
    @Test void mutationPreconditionsAndPayloadsRemainStrict()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);when(admin.getIdentityAccount(any(),any())).thenReturn(account());var mvc=mutationMvc(a,current,admin,mock(IdentityGrantCommands.class));assertEquals(428,mvc.perform(mutation("disable","{}")).andReturn().getResponse().getStatus());assertEquals(400,mvc.perform(mutation("disable","{}").header("If-Match","W/\"v1\"")).andReturn().getResponse().getStatus());for(String body:List.of("{}","{\"reason\":\"one\",\"reason\":\"two\"}","{\"reason\":\"ok\",\"actorId\":\"synthetic\"}"))assertEquals(400,mvc.perform(mutation("disable",body).header("If-Match","\"v1\"").header("Idempotency-Key",UUID.randomUUID())).andReturn().getResponse().getStatus());verify(admin,never()).disableIdentityAccount(any());when(admin.disableIdentityAccount(any())).thenReturn(new IdentityGrantCommands.Result(account(),1,true));assertEquals(200,mvc.perform(mutation("disable","{\"reason\":\" \"}").header("If-Match","\"v1\"").header("Idempotency-Key",UUID.randomUUID())).andReturn().getResponse().getStatus());}
    @Test void selfManagementCannotReachPreconditionsOrMutation()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);var mvc=mutationMvc(a,current,admin,mock(IdentityGrantCommands.class));assertEquals(403,mvc.perform(post("/api/v1/admin/users/"+ACCOUNT+"/disable").secure(true).header("Authorization","Bearer "+tokens.issue(grant())).contentType("application/json").content("{}")).andReturn().getResponse().getStatus());verifyNoInteractions(admin);}
    @Test void completedMutationAttestsActivityAfterApplicationSuccess()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());doAnswer(call->{assertEquals(SESSION,a.admit(CurrentSessionAdmission.Operation.MEANINGFUL_ACTIVITY,call.getArgument(0)).sessionId());return null;}).when(current).recordMeaningfulActivity(any());var admin=mock(IdentityAdministrationCommands.class);when(admin.getIdentityAccount(any(),any())).thenReturn(account());when(admin.disableIdentityAccount(any())).thenReturn(new IdentityGrantCommands.Result(account(),1,false));var r=mutationMvc(a,current,admin,mock(IdentityGrantCommands.class)).perform(mutation("disable","{\"reason\":\"Synthetic reason\"}").header("If-Match","\"v1\"").header("Idempotency-Key",UUID.randomUUID())).andReturn().getResponse();assertEquals(200,r.getStatus());var order=inOrder(admin,current);order.verify(current).getIdentityMe(any());order.verify(admin).getIdentityAccount(any(),any());order.verify(admin).disableIdentityAccount(any());order.verify(current).recordMeaningfulActivity(any());}
    @Test void receiptReplayDoesNotQualifyAsMeaningfulActivity()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);when(admin.getIdentityAccount(any(),any())).thenReturn(account());when(admin.disableIdentityAccount(any())).thenReturn(new IdentityGrantCommands.Result(account(),1,true));assertEquals(200,mutationMvc(a,current,admin,mock(IdentityGrantCommands.class)).perform(mutation("disable","{\"reason\":\"Synthetic reason\"}").header("If-Match","\"v1\"").header("Idempotency-Key",UUID.randomUUID())).andReturn().getResponse().getStatus());verify(current,never()).recordMeaningfulActivity(any());when(admin.disableIdentityAccount(any())).thenThrow(new IllegalStateException("synthetic-private-failure-marker"));var rejected=mutationMvc(a,current,admin,mock(IdentityGrantCommands.class)).perform(mutation("disable","{\"reason\":\"Synthetic reason\"}").header("If-Match","\"v1\"").header("Idempotency-Key",UUID.randomUUID())).andReturn().getResponse();assertEquals(401,rejected.getStatus());assertFalse(rejected.getContentAsString().contains("synthetic-private-failure-marker"));verify(current,never()).recordMeaningfulActivity(any());}
    @Test void grantWireUsesVerifiedSessionAndAcceptedFieldsOnly()throws Exception {var a=new ProductionAccessAdmission((s,u,v)->NOW);var current=mock(IdentityCurrentSessionCommands.class);when(current.getIdentityMe(any())).thenReturn(account());var admin=mock(IdentityAdministrationCommands.class);when(admin.getIdentityAccount(any(),any())).thenReturn(account());var grants=mock(IdentityGrantCommands.class);when(grants.replaceIdentityGrants(any())).thenAnswer(call->{IdentityGrantCommands.Command c=call.getArgument(0);assertEquals(SESSION,c.sessionId());assertEquals(1,c.expectedVersion());assertEquals("Synthetic reason",c.reason());return new IdentityGrantCommands.Result(account(),1,true);});var body="{\"reason\":\"Synthetic reason\",\"grants\":[{\"role\":\"IDENTITY_MANAGEMENT\",\"scopeType\":\"IDENTITY\",\"scopeId\":\"20000000-0000-4000-8000-000000000004\"}]}";var r=mutationMvc(a,current,admin,grants).perform(put("/api/v1/admin/users/20000000-0000-4000-8000-000000000003/grants").secure(true).header("Authorization","Bearer "+tokens.issue(grant())).header("If-Match","\"v1\"").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andReturn().getResponse();assertEquals(200,r.getStatus());assertEquals("\"v1\"",r.getHeader("ETag"));assertFalse(r.getContentAsString().contains("appliedVersion"));verify(grants).replaceIdentityGrants(any());}
}
